#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>

using namespace std;

/**
 * Problem: 22351 - Quirksome Squares
 * 
 * 解題思路：
 * 1. 特性定義：一個 n 位數，切成兩半分別為 a 和 b，若 (a+b)^2 等於原數，則為 quirksome number。
 * 2. 由於 n 是偶數 (2, 4, 6, 8)，我們可以令 n = 2k。
 * 3. 數值範圍：
 *    - 2位數：00-99，a, b 為 1 位數。
 *    - 8位數：00000000-99999999，a, b 為 4 位數。
 * 4. 關鍵觀察：如果 (a+b)^2 = 原數，那麼 a+b 的平方根一定在 [0, 10^k - 1] 之間。
 * 5. 演算法：
 *    - 對於給定的 n，令 k = n/2。
 *    - 遍歷 i 從 0 到 10^k - 1。
 *    - 計算 square = i * i。
 *    - 將 square 拆分為左半部 left 和右半部 right（right = square % 10^k, left = square / 10^k）。
 *    - 如果 left + right == i，則 square 是一個 quirksome number。
 * 6. 注意輸出需包含前導零。
 */

void findQuirksome(int n) {
    int k = n / 2;
    long long mod = 1;
    for(int i=0; i<k; i++) mod *= 10;

    for (long long i = 0; i < mod; i++) {
        long long square = i * i;
        long long left = square / mod;
        long long right = square % mod;
        if (left + right == i) {
            cout << setfill('0') << setw(n) << square << endl;
        }
    }
}

int main() {
    int n;
    while (cin >> n) {
        findQuirksome(n);
    }
    return 0;
}
